package com.securevault.service;
import com.securevault.entity.*;import com.securevault.repository.UserSessionRepository;import org.springframework.stereotype.Service;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
@Service public class SessionService{private final UserSessionRepository repo;public SessionService(UserSessionRepository r){repo=r;}public String hash(String token){try{byte[] b=MessageDigest.getInstance("SHA-256").digest(token.getBytes(StandardCharsets.UTF_8));return Base64.getEncoder().encodeToString(b);}catch(Exception e){throw new RuntimeException(e);}}public UserSession create(User u,String token,String ip,String browser,String device){UserSession s=new UserSession();s.setUser(u);s.setTokenHash(hash(token));s.setIpAddress(ip);s.setBrowser(browser);s.setDevice(device);return repo.save(s);}public List<UserSession> list(User u){return repo.findByUserOrderByLastSeenDesc(u);}public void revoke(Long id,User u){UserSession s=repo.findById(id).orElseThrow();if(!s.getUser().getId().equals(u.getId()))throw new RuntimeException("Forbidden");s.setActive(false);repo.save(s);}}
